    /* Planet compliance page */
    "planet.h1": "Planet / \u0414\u04d9\u043b\u0435\u043b / \u0421\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442 (MVP)",
    "planet.subtitle": "\u0411\u0456\u0440\u044b\u04a3\u0493\u0430\u0439 \u043a\u043e\u043d\u0432\u0435\u0439\u0435\u0440: \u043a\u0430\u043d\u043e\u043d\u0434\u0430\u0443 \u2192 \u0432\u0430\u043b\u0438\u0434\u0430\u0442\u043e\u0440\u043b\u0430\u0440 \u2192 evidenceRoot \u2192 \u049b\u043e\u043b \u049b\u043e\u0439\u044b\u043b\u0493\u0430\u043d \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442. Code/web \u0441\u0435\u0433\u043c\u0435\u043d\u0442\u0442\u0435\u0440\u0456 \u0441\u0456\u0437\u0434\u0456\u04a3 \u043a\u043e\u0434\u044b\u04a3\u044b\u0437\u0493\u0430 \u043d\u0435\u0433\u0456\u0437\u0434\u0435\u043b\u0456\u043f \u043a\u04e9\u0440\u0441\u0435\u0442\u0456\u043b\u0435\u0434\u0456.",
    "planet.betaBanner.strong": "Planet \u2014 AEVION \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430\u0441\u044b\u043d\u044b\u04a3 \u0435\u04a3 \u0436\u0430\u04a3\u0430 \u0436\u04d9\u043d\u0435 \u0436\u044b\u043b\u0434\u0430\u043c \u04e9\u0437\u0433\u0435\u0440\u0435\u0442\u0456\u043d \u049b\u0430\u0431\u0430\u0442\u044b.",
    "planet.betaBanner.pre": "\u0416\u0430\u04a3\u0430 \u0432\u0430\u043b\u0438\u0434\u0430\u0442\u043e\u0440\u043b\u0430\u0440, \u049b\u043e\u0441\u044b\u043c\u0448\u0430\u043b\u0430\u0440 \u0436\u04d9\u043d\u0435 compliance \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0439\u043b\u0435\u0440\u0456 \u04af\u043d\u0435\u043c\u0456 \u049b\u043e\u0441\u044b\u043b\u044b\u043f \u0442\u04b1\u0440\u0430\u0434\u044b, \u0441\u043e\u043d\u0434\u044b\u049b\u0442\u0430\u043d \u04e9\u0437\u0433\u0435\u0440\u0456\u0441\u0442\u0435\u0440\u0433\u0435 \u0434\u0430\u0439\u044b\u043d \u0431\u043e\u043b\u044b\u04a3\u044b\u0437 \u2014 \u043a\u0435\u0439\u0431\u0456\u0440 \u043a\u0435\u043c\u0448\u0456\u043b\u0456\u043a\u0442\u0435\u0440 \u0434\u0435 \u0431\u043e\u043b\u0443\u044b \u043c\u04af\u043c\u043a\u0456\u043d. \u0415\u0433\u0435\u0440 \u0431\u0456\u0440 \u043d\u04d9\u0440\u0441\u0435 \u043a\u04af\u0442\u043a\u0435\u043d\u0434\u0435\u0439 \u0436\u04b1\u043c\u044b\u0441 \u0456\u0441\u0442\u0435\u043c\u0435\u0441\u0435,",
    "planet.betaBanner.cta": "\u0431\u0456\u0437\u0433\u0435 \u0445\u0430\u0431\u0430\u0440\u043b\u0430\u04a3\u044b\u0437",
    "planet.betaBanner.post": "\u2014 \u0431\u04b1\u043b \u043a\u0435\u0440\u0456 \u0431\u0430\u0439\u043b\u0430\u043d\u044b\u0441 \u0431\u0456\u0437\u0434\u0456\u04a3 \u043a\u0435\u043b\u0435\u0441\u0456 \u049b\u0430\u0434\u0430\u043c\u0434\u0430\u0440\u044b\u043c\u044b\u0437\u0493\u0430 \u0442\u0456\u043a\u0435\u043b\u0435\u0439 \u04d9\u0441\u0435\u0440 \u0435\u0442\u0435\u0434\u0456.",
