  // API docs /bank/api
  "api.title": "AEVION Bank \u2014 API Reference",
  "api.subtitle": "\u041a\u0443\u0440\u0430\u0442\u043e\u0440\u0441\u043a\u0430\u044f \u0432\u044b\u0431\u043e\u0440\u043a\u0430 \u0434\u043b\u044f \u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u0447\u0438\u043a\u043e\u0432. \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0438\u0441\u0442\u0438\u043d\u044b \u2014 OpenAPI \u043f\u043e \u0441\u0441\u044b\u043b\u043a\u0435 \u043d\u0438\u0436\u0435.",
  "api.backToBank": "\u041d\u0430\u0437\u0430\u0434 \u0432 AEVION Bank",
  "api.openapi.cta": "\u041f\u043e\u043b\u043d\u044b\u0439 OpenAPI \u2192",
  "api.varsLabel": "\u041f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0435 (\u043f\u043e\u0434\u0441\u0442\u0430\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u0432 curl-\u043f\u0440\u0438\u043c\u0435\u0440\u044b \u043d\u0438\u0436\u0435)",
  "api.bearer": "\u043d\u0443\u0436\u043d\u0430 \u0430\u0432\u0442\u043e\u0440\u0438\u0437\u0430\u0446\u0438\u044f",
  "api.curl": "\u0417\u0430\u043f\u0440\u043e\u0441",
  "api.response": "\u041e\u0442\u0432\u0435\u0442 (\u043f\u0440\u0438\u043c\u0435\u0440)",
  "api.copy": "\u0421\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c",
  "api.copied": "\u0421\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u043d\u043e",
  "api.disclaimer": "\u041f\u0430\u0433\u0438\u043d\u0430\u0446\u0438\u044f, rate-limits, \u0438\u0434\u0435\u043c\u043f\u043e\u0442\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u044c \u0438 \u0432\u0435\u0431\u0445\u0443\u043a\u0438 \u0443\u0436\u0435 \u0440\u0430\u0431\u043e\u0442\u0430\u044e\u0442 \u2014 \u043f\u043e\u043b\u043d\u044b\u0435 \u0441\u0445\u0435\u043c\u044b \u0432 OpenAPI. \u0412\u0441\u0451 \u0437\u0430 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u043c\u0438 test-net (\u043a\u0430\u0440\u0442\u044b, \u0444\u0438\u0430\u0442, KYC, \u043a\u0440\u0435\u0434\u0438\u0442\u044b) \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043f\u0430\u0440\u0442\u043d\u0451\u0440\u0441\u043a\u0438\u0445 \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u043e\u0432 \u0438 \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0438.",
  "api.group.auth": "\u0410\u0443\u0442\u0435\u043d\u0442\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f",
  "api.group.wallet": "\u041a\u043e\u0448\u0435\u043b\u0451\u043a \u00b7 \u043f\u0435\u0440\u0435\u0432\u043e\u0434\u044b \u00b7 \u0440\u0435\u0435\u0441\u0442\u0440",
  "api.group.signing": "\u041a\u0440\u0438\u043f\u0442\u043e\u0433\u0440\u0430\u0444\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043f\u043e\u0434\u043f\u0438\u0441\u0438",
