  "circlesPage.empty.title": "\u041a\u0440\u0443\u0433\u043e\u0432 \u043f\u043e\u043a\u0430 \u043d\u0435\u0442.",
  "circlesPage.empty.body": "\u041e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u043a\u043e\u0448\u0435\u043b\u0451\u043a, \u043f\u0440\u043e\u043a\u0440\u0443\u0442\u0438\u0442\u0435 \u0434\u043e Social Circles \u0438 \u0441\u043e\u0437\u0434\u0430\u0439\u0442\u0435 \u043f\u0435\u0440\u0432\u044b\u0439. \u0414\u043e\u0431\u0430\u0432\u044c\u0442\u0435 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043a\u043e\u043d\u0442\u0430\u043a\u0442\u043e\u0432 \u2014 \u0438 \u043b\u044e\u0431\u043e\u0439 \u043c\u043e\u0436\u0435\u0442 \u0437\u0430\u043f\u0440\u0430\u0448\u0438\u0432\u0430\u0442\u044c \u0438\u043b\u0438 \u0437\u0430\u043a\u0440\u044b\u0432\u0430\u0442\u044c \u0434\u0435\u043d\u044c\u0433\u0438 \u0432\u043d\u0443\u0442\u0440\u0438 \u0433\u0440\u0443\u043f\u043f\u044b.",
  "circlesPage.empty.cta": "\u0421\u043e\u0437\u0434\u0430\u0442\u044c \u043a\u0440\u0443\u0433",
  "circlesPage.cta.kicker": "\u0423\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0432 /bank",
  "circlesPage.cta.title": "\u042d\u0442\u0430 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0430 \u2014 \u043e\u0431\u0437\u043e\u0440.",
  "circlesPage.cta.body": "\u041e\u0442\u043f\u0440\u0430\u0432\u043a\u0430 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0439, \u043f\u043b\u0430\u0442\u0435\u0436\u0435\u0439 \u0438 \u0434\u043e\u0431\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432 \u2014 \u0432\u043d\u0443\u0442\u0440\u0438 \u043a\u043e\u0448\u0435\u043b\u044c\u043a\u0430. \u041d\u0430 \u044d\u0442\u043e\u0439 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0435 \u0443\u0434\u043e\u0431\u043d\u043e \u0441\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u0441\u0435 \u043a\u0440\u0443\u0433\u0438 \u043e\u0434\u043d\u0438\u043c \u0432\u0437\u0433\u043b\u044f\u0434\u043e\u043c.",
  "circlesPage.cta.contacts": "\u0410\u0434\u0440\u0435\u0441\u043d\u0430\u044f \u043a\u043d\u0438\u0433\u0430",

  // Glossary /bank/glossary
  "glossaryPage.kicker": "\u0413\u043b\u043e\u0441\u0441\u0430\u0440\u0438\u0439",
  "glossaryPage.headline": "\u041a\u0430\u0436\u0434\u043e\u0435 \u043f\u043e\u043d\u044f\u0442\u0438\u0435 \u2014 \u0432 \u043e\u0434\u0438\u043d \u0430\u0431\u0437\u0430\u0446.",
  "glossaryPage.lede": "{count} \u0442\u0435\u0440\u043c\u0438\u043d\u043e\u0432 \u0432 \u0441\u0435\u043c\u0438 \u0433\u0440\u0443\u043f\u043f\u0430\u0445 \u2014 \u0432\u0430\u043b\u044e\u0442\u0430, \u0434\u043e\u0432\u0435\u0440\u0438\u0435, \u0441\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u0438\u044f, \u043a\u0440\u0435\u0434\u0438\u0442, \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u043e\u0441\u0442\u044c, \u0441\u043e\u0446\u0438\u0430\u043b\u043a\u0430, \u044d\u043a\u043e\u0441\u0438\u0441\u0442\u0435\u043c\u0430. \u041f\u043e\u0438\u0441\u043a, \u0447\u0442\u043e\u0431\u044b \u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c \u043a \u0442\u0435\u0440\u043c\u0438\u043d\u0443, \u0438\u043b\u0438 \u043f\u0440\u043e\u043a\u0440\u0443\u0442\u043a\u0430 \u043f\u043e \u0433\u0440\u0443\u043f\u043f\u0430\u043c.",
  "glossaryPage.searchPlaceholder": "\u041f\u043e\u0438\u0441\u043a \u043f\u043e \u0442\u0435\u0440\u043c\u0438\u043d\u0430\u043c \u0438 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f\u043c\u2026",
  "glossaryPage.searchAria": "\u041f\u043e\u0438\u0441\u043a \u043f\u043e \u0433\u043b\u043e\u0441\u0441\u0430\u0440\u0438\u044e",
