  "primer.eyebrow": "AEVION Bank \u00b7 \u041a\u043e\u043d\u0446\u0435\u043f\u0446\u0438\u044f",
  "primer.title.a": "\u0421\u0456\u0437\u0434\u0435\u0440\u043c\u0435\u043d",
  "primer.title.b": "\u0431\u0456\u0440\u0433\u0435",
  "primer.title.c": "\u0430\u049b\u0448\u0430 \u0442\u0430\u0431\u0430\u0442\u044b\u043d \u0431\u0430\u043d\u043a \u2014 \u0441\u0456\u0437\u0434\u0435\u043d \u0435\u043c\u0435\u0441.",
  "primer.body":
    "AEVION Bank \u2014 27 \u04e9\u043d\u0456\u043c\u043d\u0435\u043d \u0442\u04b1\u0440\u0430\u0442\u044b\u043d \u044d\u043a\u043e\u0436\u04af\u0439\u0435\u043d\u0456\u04a3 \u049b\u0430\u0440\u0436\u044b \u049b\u0430\u0431\u0430\u0442\u044b. \u0421\u0456\u0437\u0434\u0456\u04a3 \u04d9\u043c\u0438\u044f\u043d\u044b\u04a3\u044b\u0437 IP-\u0434\u0435\u043d (QRight) \u0440\u043e\u044f\u043b\u0442\u0438\u0434\u0456, \u0448\u0430\u0445\u043c\u0430\u0442\u0442\u0430\u043d (CyberChess) \u0436\u04af\u043b\u0434\u0435\u043b\u0435\u0440\u0434\u0456, Planet \u0431\u043e\u043d\u0443\u0441\u0442\u0430\u0440\u044b\u043d \u0436\u04d9\u043d\u0435 P2P-\u0430\u0443\u0434\u0430\u0440\u044b\u043c\u0434\u0430\u0440\u0434\u044b \u043a\u04e9\u0440\u0435\u0434\u0456 \u2014 \u043c\u04b1\u043d\u044b\u04a3 \u0431\u04d9\u0440\u0456 \u0431\u0456\u0440\u044b\u04a3\u0493\u0430\u0439 Trust Score \u049b\u0430\u043b\u044b\u043f\u0442\u0430\u0441\u0442\u044b\u0440\u0430\u0434\u044b, \u043e\u043b \u0430\u0432\u0430\u043d\u0441\u0442\u0430\u0440\u0434\u044b, \u0434\u04d9\u0440\u0435\u0436\u0435\u043b\u0435\u0440\u0434\u0456 \u0436\u04d9\u043d\u0435 \u0430\u0440\u0442\u044b\u049b\u0448\u044b\u043b\u044b\u049b\u0442\u0430\u0440\u0434\u044b \u0430\u0448\u0430\u0434\u044b. \u0416\u0435\u043a\u0435 AI Copilot \u043c\u04b1\u043d\u044b \u0441\u0456\u0437 \u04af\u0448\u0456\u043d \u0431\u0430\u049b\u044b\u043b\u0430\u0439\u0434\u044b, \u0430\u043b Autopilot \u0448\u0430\u0493\u044b\u043d \u0441\u043e\u043c\u0430\u043b\u0430\u0440\u0434\u044b \u043c\u0430\u049b\u0441\u0430\u0442\u0442\u0430\u0440\u044b\u04a3\u044b\u0437\u0493\u0430 \u0436\u0456\u0431\u0435\u0440\u0435\u0434\u0456 \u2014 \u0440\u04b1\u049b\u0441\u0430\u0442\u044b\u04a3\u044b\u0437\u0431\u0435\u043d, \u043b\u0438\u043c\u0438\u0442\u043f\u0435\u043d, \u0430\u0443\u0434\u0438\u0442\u043f\u0435\u043d.",
  "primer.audience.user": "\u0415\u0433\u0435\u0440 \u0436\u0438\u043d\u0430\u049b \u04af\u0448\u0456\u043d \u043a\u0435\u043b\u0441\u0435\u04a3\u0456\u0437",
  "primer.audience.creator": "\u0415\u0433\u0435\u0440 \u0436\u0430\u0441\u0430\u0441\u0430\u04a3\u044b\u0437",
  "primer.audience.investor": "\u0415\u0433\u0435\u0440 \u0431\u0430\u0493\u0430\u043b\u0430\u0441\u0430\u04a3\u044b\u0437",
  "primer.user.headline": "\u041c\u0430\u049b\u0441\u0430\u0442\u0442\u0430\u0440\u0493\u0430 \u0436\u0435\u0442\u0443\u0433\u0435 \u0431\u0435\u043b\u0441\u0435\u043d\u0434\u0456 \u043a\u04e9\u043c\u0435\u043a\u0442\u0435\u0441\u0435\u0442\u0456\u043d \u04d9\u043c\u0438\u044f\u043d",
  "primer.user.b1": "AI Copilot \u049b\u04b1\u0440\u044b\u043b\u0493\u044b\u0434\u0430 8 \u0441\u0438\u0433\u043d\u0430\u043b\u0434\u044b \u0431\u0430\u049b\u044b\u043b\u0430\u0439\u0434\u044b \u0436\u04d9\u043d\u0435 \u0430\u0440\u0442\u044b\u049b \u0448\u044b\u0493\u044b\u043d\u0493\u0430 \u0434\u0435\u0439\u0456\u043d \u0435\u0441\u043a\u0435\u0440\u0442\u0435\u0434\u0456.",
  "primer.user.b2": "Autopilot \u0430\u0440\u0442\u0442\u0430 \u049b\u0430\u043b\u0493\u0430\u043d \u043c\u0430\u049b\u0441\u0430\u0442\u0442\u0430\u0440\u0493\u0430 \u0448\u0430\u0493\u044b\u043d \u0441\u043e\u043c\u0430\u043b\u0430\u0440\u0434\u044b \u0430\u0443\u0434\u0430\u0440\u0430 \u0430\u043b\u0430\u0434\u044b \u2014 \u049b\u0430\u0442\u0430\u04a3 \u043a\u04af\u043d\u0434\u0456\u043a \u043b\u0438\u043c\u0438\u0442\u043f\u0435\u043d.",
  "primer.user.b3": "Panic Freeze \u0448\u044b\u0493\u044b\u0441 \u0430\u0443\u0434\u0430\u0440\u044b\u043c\u0434\u0430\u0440\u0434\u044b \u0431\u0456\u0440 \u0440\u0435\u0442 \u0431\u0430\u0441\u0443\u0434\u0430 \u0431\u043b\u043e\u043a\u0442\u0430\u0439\u0434\u044b, 5 \u043c\u0438\u043d\u0443\u0442\u0442\u044b\u049b \u043e\u0439\u043b\u0430\u043d\u0443 \u0442\u0435\u0440\u0435\u0437\u0435\u0441\u0456\u043c\u0435\u043d.",
  "primer.creator.headline": "\u0421\u0456\u0437\u0434\u0456\u04a3 \u0431\u0435\u0434\u0435\u043b\u0456\u04a3\u0456\u0437 \u0441\u0456\u0437\u0434\u0456\u04a3 \u043a\u0440\u0435\u0434\u0438\u0442\u0456\u04a3\u0456\u0437 \u0431\u043e\u043b\u0430\u0434\u044b",
  "primer.creator.b1": "Trust Score 8 \u0444\u0430\u043a\u0442\u043e\u0440\u0434\u044b \u0431\u0456\u0440\u0456\u043a\u0442\u0456\u0440\u0435\u0434\u0456: QRight (IP), CyberChess, Planet \u0436\u04d9\u043d\u0435 \u0431\u0430\u043d\u043a \u0431\u0435\u043b\u0441\u0435\u043d\u0434\u0456\u043b\u0456\u0433\u0456.",
  "primer.creator.b2": "QRight-\u0442\u0435\u043d \u0440\u043e\u044f\u043b\u0442\u0438 \u0430\u0493\u044b\u043d\u044b \u0442\u0456\u043a\u0435\u043b\u0435\u0439 \u04d9\u043c\u0438\u044f\u043d\u0493\u0430 \u0442\u04af\u0441\u0435\u0434\u0456 \u2014 \u0433\u043e\u043b\u043e\u0433\u0440\u0430\u0444\u0438\u044f\u043b\u044b\u049b QR \u0430\u0440\u049b\u044b\u043b\u044b \u043c\u0430\u049b\u0441\u0430\u0442\u0442\u0430\u0440\u043c\u0435\u043d \u0431\u04e9\u043b\u0456\u0441\u0456\u04a3\u0456\u0437.",
  "primer.creator.b3": "\u0416\u0435\u0442\u0456\u0441\u0442\u0456\u043a\u0442\u0435\u0440 \u0434\u04d9\u0440\u0435\u0436\u0435\u043b\u0435\u0440\u0434\u0456 \u0430\u0448\u0430\u0434\u044b; \u0434\u04d9\u0440\u0435\u0436\u0435\u043b\u0435\u0440 27 AEVION \u043c\u043e\u0434\u0443\u043b\u0456\u043d\u0434\u0435\u0433\u0456 \u0430\u0432\u0430\u043d\u0441 \u043f\u0435\u043d \u0430\u0440\u0442\u044b\u049b\u0448\u044b\u043b\u044b\u049b\u0442\u0430\u0440\u0434\u044b \u0430\u0448\u0430\u0434\u044b.",
  "primer.investor.headline": "Capital-light \u0444\u0438\u043d\u0442\u0435\u0445 ecosystem moat-\u043f\u0435\u043d",
  "primer.investor.b1": "Client-side \u0435\u0433\u0435\u043c\u0435\u043d\u0434\u0456\u043a: \u043c\u0430\u049b\u0441\u0430\u0442\u0442\u0430\u0440, recurring, \u0441\u044b\u0439\u043b\u044b\u049b\u0442\u0430\u0440 \u2014 \u0431\u04d9\u0440\u0456 \u049b\u04b1\u0440\u044b\u043b\u0493\u044b\u0434\u0430. Vendor lock-in \u0436\u043e\u049b.",
  "primer.investor.b2": "Regulator-ready by design: QSign HMAC \u0430\u0443\u0434\u0438\u0442, Shamir SSS 2-of-3, v1 \u04af\u0448\u0456\u043d \u043d\u0435\u0441\u0438\u0435 \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u044f\u0441\u044b \u049b\u0430\u0436\u0435\u0442 \u0435\u043c\u0435\u0441.",
  "primer.investor.b3": "Trust Graph \u2014 \u04e9\u0441\u0456\u043f \u043a\u0435\u043b\u0435 \u0436\u0430\u0442\u049b\u0430\u043d moat: AEVION-\u043d\u044b\u04a3 27 \u04e9\u043d\u0456\u043c\u0456\u043d\u0456\u04a3 \u04d9\u0440\u049b\u0430\u0439\u0441\u044b\u0441\u044b Trust \u0444\u0430\u043a\u0442\u043e\u0440\u044b\u043d \u049b\u043e\u0441\u0430\u0434\u044b.",
