  "explore.card.trip.hint": "\u041a\u04af\u043d \u0430\u0440\u0430\u043b\u044b\u0493\u044b\u043c\u0435\u043d \u0441\u0430\u043f\u0430\u0440 \u0431\u044e\u0434\u0436\u0435\u0442\u0456 \u0436\u04d9\u043d\u0435 \u043a\u04af\u043d\u0434\u0435\u043b\u0456\u043a\u0442\u0456 \u049b\u0430\u0440\u049b\u044b\u043d \u043c\u0435\u043d \u0441\u0430\u043f\u0430\u0440 \u0441\u043e\u04a3\u044b\u043d\u044b\u04a3 \u0431\u043e\u043b\u0436\u0430\u043c\u044b.",
  "explore.card.brief.title": "\u0410\u043f\u0442\u0430\u043b\u044b\u049b \u0431\u0440\u0438\u0444\u0438\u043d\u0433",
  "explore.card.brief.hint": "AI \u0441\u0442\u0438\u043b\u0456\u043d\u0434\u0435 \u0430\u043f\u0442\u0430\u043b\u044b\u049b \u0434\u0430\u0439\u0434\u0436\u0435\u0441\u0442 \u2014 \u0442\u043e\u043f \u049b\u043e\u0437\u0493\u0430\u043b\u044b\u0441\u0442\u0430\u0440, \u0430\u043d\u043e\u043c\u0430\u043b\u0438\u044f\u043b\u0430\u0440, \u043c\u0438\u043b\u044c\u0448\u043e\u0443\u0442\u0430\u0440, \u0436\u0435\u0440\u0433\u0456\u043b\u0456\u043a\u0442\u0456 \u0435\u0441\u0435\u043f\u0442\u0435\u043b\u0433\u0435\u043d.",
  "explore.card.achievements.title": "\u0416\u0435\u0442\u0456\u0441\u0442\u0456\u043a\u0442\u0435\u0440",
  "explore.card.achievements.hint": "\u0428\u044b\u0493\u044b\u043d \u04d9\u0434\u0435\u0442\u0442\u0435\u0440\u0456, \u0430\u0493\u044b\u043d\u0434\u0430\u0440 \u0436\u04d9\u043d\u0435 trust-\u0431\u0430\u043b\u043b \u0431\u043e\u0439\u044b\u043d\u0448\u0430 \u0430\u0448\u044b\u043b\u0493\u0430\u043d \u0431\u0435\u043b\u0433\u0456\u043b\u0435\u0440 \u043c\u0435\u043d \u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0441.",
  "explore.card.challenges.title": "\u0427\u0435\u043b\u043b\u0435\u043d\u0434\u0436\u0442\u0435\u0440",
  "explore.card.challenges.hint": "No-spend \u0441\u0435\u0440\u0438\u044f\u043b\u0430\u0440\u044b\u043c\u0435\u043d \u0436\u0438\u043d\u0430\u049b \u0447\u0435\u043b\u043b\u0435\u043d\u0434\u0436\u0442\u0435\u0440\u0456 \u2014 \u0441\u0430\u043b\u0430\u0443\u0430\u0442\u0442\u044b \u049b\u0430\u0440\u0436\u044b \u04d9\u0434\u0435\u0442\u0442\u0435\u0440\u0456\u043d \u049b\u0430\u043b\u044b\u043f\u0442\u0430\u0441\u0442\u044b\u0440\u0430\u0434\u044b.",
  "explore.card.networth.title": "\u0422\u0430\u0437\u0430 \u043a\u0430\u043f\u0438\u0442\u0430\u043b",
  "explore.card.networth.hint": "\u04d8\u043c\u0438\u044f\u043d, vaults, royalty, \u0448\u0430\u0445\u043c\u0430\u0442 \u0436\u04af\u043b\u0434\u0435\u0441\u0456 \u2014 \u04d9\u0440 \u049b\u0430\u0431\u0430\u0442 \u0431\u0456\u0440 \u0441\u0430\u043d\u0434\u0430.",
  "explore.card.timetravel.title": "\u0423\u0430\u049b\u044b\u0442 \u043c\u0430\u0448\u0438\u043d\u0430\u0441\u044b",
  "explore.card.timetravel.hint": "\u04d8\u043c\u0438\u044f\u043d\u043d\u044b\u04a3 \u043a\u04af\u0439\u0456\u043d \u043a\u0435\u0437 \u043a\u0435\u043b\u0433\u0435\u043d \u04e9\u0442\u043a\u0435\u043d \u0430\u0439\u0493\u0430 \u049b\u0430\u0439\u0442\u0430\u0440\u044b\u04a3\u044b\u0437 \u2014 \u0431\u0430\u043b\u0430\u043d\u0441, royalty \u0436\u04d9\u043d\u0435 \u0442\u04b1\u0440\u0430\u049b\u0442\u044b \u0435\u0440\u0435\u0436\u0435\u043b\u0435\u0440 \u0441\u043e\u043b \u0441\u04d9\u0442\u0442\u0435.",
  "explore.card.constellation.title": "\u041a\u0430\u043f\u0438\u0442\u0430\u043b \u0448\u043e\u049b\u0436\u04b1\u043b\u0434\u044b\u0437\u044b",
  "explore.card.constellation.hint": "\u0411\u0430\u0440\u043b\u044b\u049b \u043a\u0456\u0440\u0456\u0441 \u0430\u0493\u044b\u043d\u0434\u0430\u0440\u044b, \u043c\u0430\u049b\u0441\u0430\u0442\u0442\u0430\u0440, vaults \u0436\u04d9\u043d\u0435 \u0442\u04b1\u0440\u0430\u049b\u0442\u044b \u0435\u0440\u0435\u0436\u0435\u043b\u0435\u0440 \u2014 \u0431\u0456\u0440 \u0448\u043e\u049b\u0436\u04b1\u043b\u0434\u044b\u0437 \u043a\u0430\u0440\u0442\u0430\u0441\u044b.",
  "explore.card.wishlist.title": "\u0422\u0456\u043b\u0435\u043a\u0442\u0435\u0440",
  "explore.card.wishlist.hint": "\u0416\u0438\u043d\u0430\u043f \u0436\u0430\u0442\u049b\u0430\u043d \u0437\u0430\u0442\u0442\u0430\u0440 \u2014 \u04d9\u0440\u049b\u0430\u0439\u0441\u044b\u0441\u044b\u043d\u044b\u04a3 \u0436\u0435\u043a\u0435 \u0435\u0441\u0435\u043f\u0442\u0435\u0433\u0456\u0448\u0456 \u043c\u0435\u043d \u043c\u0430\u049b\u0441\u0430\u0442\u044b.",
  "explore.card.loyalty.title": "\u0410\u0434\u0430\u043b\u0434\u044b\u049b \u049b\u043e\u0439\u043c\u0430\u0441\u044b",
  "explore.card.loyalty.hint": "\u0421\u044b\u0440\u0442\u049b\u044b \u0430\u0434\u0430\u043b\u0434\u044b\u049b \u0431\u0430\u0493\u0434\u0430\u0440\u043b\u0430\u043c\u0430\u043b\u0430\u0440\u044b \u2014 \u0431\u0430\u043b\u043b\u0434\u0430\u0440, \u043c\u0438\u043b\u044c\u0434\u0435\u0440, \u043a\u0443\u043f\u043e\u043d\u0434\u0430\u0440 \u2014 \u043c\u0435\u0440\u0437\u0456\u043c\u0456 \u0442\u0443\u0440\u0430\u043b\u044b \u0445\u0430\u0431\u0430\u0440\u043b\u0430\u043c\u0430.",
  "explore.card.cooldown.title": "Cool-down \u043a\u0435\u0437\u0435\u0433\u0456",
  "explore.card.cooldown.hint": "\u0418\u043c\u043f\u0443\u043b\u044c\u0441\u043a\u0435 \u049b\u0430\u0440\u0441\u044b 12-72\u0441 \u04b1\u0441\u0442\u0430\u0443. \u04d8\u043c\u0438\u044f\u043d \u043a\u04af\u0442\u0435\u0434\u0456 \u2014 \u0441\u0456\u0437 \u0448\u044b\u043d\u044b\u043c\u0435\u043d \u043c\u0430\u04a3\u044b\u0437\u0434\u044b \u0431\u043e\u043b\u0493\u0430\u043d\u0434\u0430 \u0493\u0430\u043d\u0430 \u0440\u0430\u0441\u0442\u0430\u0439\u0441\u044b\u0437.",
  "explore.card.changelog.title": "Changelog",
  "explore.card.changelog.hint": "\u0411\u0430\u0440\u043b\u044b\u049b \u0436\u0435\u0442\u043a\u0456\u0437\u0456\u043b\u0433\u0435\u043d Bank-\u0444\u0438\u0447\u0430\u043b\u0430\u0440\u0434\u044b\u04a3 \u0430\u0448\u044b\u049b \u0442\u0430\u0439\u043c\u043b\u0430\u0439\u043d\u044b, \u0430\u043f\u0442\u0430\u043b\u0430\u0440 \u043c\u0435\u043d \u0442\u0435\u0433\u0442\u0435\u0440 \u0431\u043e\u0439\u044b\u043d\u0448\u0430.",

