  "budgetPage.stat.projected.empty": "\u0411\u043e\u043b\u0436\u0430\u043c \u04af\u0448\u0456\u043d \u043b\u0438\u043c\u0438\u0442 \u049b\u043e\u0439\u044b\u04a3\u044b\u0437",
