  "budgetPage.status.risk": "\u049a\u0430\u0443\u0456\u043f",
  "budgetPage.status.over": "\u0410\u0441\u044b\u043f \u043a\u0435\u0442\u043a\u0435\u043d",
  "budgetPage.status.none": "\u041b\u0438\u043c\u0438\u0442\u0441\u0456\u0437",
  "budgetPage.statusBody.ontrack": "\u041e\u0441\u044b \u049b\u0430\u0440\u049b\u044b\u043d\u043c\u0435\u043d \u0430\u0439 ~{projected} \u0436\u0435\u0442\u043a\u0456\u0437\u0435\u0434\u0456 \u2014 {cap} \u043b\u0438\u043c\u0438\u0442\u0456\u043d\u0435\u043d \u0442\u04e9\u043c\u0435\u043d. \u0416\u0430\u043b\u0493\u0430\u0441\u0442\u044b\u0440\u044b\u04a3\u044b\u0437.",
  "budgetPage.statusBody.risk": "\u049a\u0430\u0440\u049b\u044b\u043d \u0430\u0439\u0434\u044b ~{projected}-\u043a\u0435 \u0448\u044b\u0493\u0430\u0440\u0430\u0434\u044b (\u043b\u0438\u043c\u0438\u0442 {cap}). \u0411\u0456\u0440 \u0441\u0430\u043d\u0430\u0442\u0442\u044b \u0442\u0430\u0440\u044b\u043b\u0442\u044b\u04a3\u044b\u0437.",
  "budgetPage.statusBody.over": "\u041e\u0441\u044b \u049b\u0430\u0440\u049b\u044b\u043d\u043c\u0435\u043d \u0430\u0439 ~{projected}-\u0442\u0435 \u0431\u0456\u0442\u0435\u0434\u0456 \u2014 {cap}-\u0442\u0430\u043d \u0436\u043e\u0493\u0430\u0440\u044b. \u0422\u04af\u0437\u0435\u0442\u0443\u0433\u0435 {days} \u043a\u04af\u043d \u049b\u0430\u043b\u0434\u044b.",
  "budgetPage.statusBody.none": "\u041b\u0438\u043c\u0438\u0442\u0442\u0435\u0440 \u04d9\u043b\u0456 \u0436\u043e\u049b \u2014 \u049b\u0430\u0440\u049b\u044b\u043d \u043c\u0435\u043d \u0431\u043e\u043b\u0436\u0430\u043c\u0434\u044b \u0430\u0448\u0443 \u04af\u0448\u0456\u043d \u0431\u0456\u0440\u0435\u0443\u0456\u043d \u049b\u043e\u0439\u044b\u04a3\u044b\u0437.",
