  "circlesPage.empty.body": "\u04d8\u043c\u0438\u044f\u043d\u0434\u044b \u0430\u0448\u044b\u043f, Social Circles-\u043a\u0435 \u0431\u0430\u0440\u044b\u043f \u0431\u0456\u0440\u0456\u043d\u0448\u0456 \u0442\u043e\u043f \u0436\u0430\u0441\u0430\u04a3\u044b\u0437. \u0411\u0456\u0440\u043d\u0435\u0448\u0435 \u043a\u043e\u043d\u0442\u0430\u043a\u0442 \u049b\u043e\u0441\u044b\u04a3\u044b\u0437 \u2014 \u043a\u0435\u0437 \u043a\u0435\u043b\u0433\u0435\u043d \u043c\u04af\u0448\u0435 \u0442\u043e\u043f \u0456\u0448\u0456\u043d\u0434\u0435 \u0430\u049b\u0448\u0430 \u0441\u04b1\u0440\u0430\u0443\u044b \u043d\u0435\u043c\u0435\u0441\u0435 \u0442\u04e9\u043b\u0435\u0443\u0456 \u043c\u04af\u043c\u043a\u0456\u043d.",
  "circlesPage.empty.cta": "\u0422\u043e\u043f \u0436\u0430\u0441\u0430\u0443",
  "circlesPage.cta.kicker": "/bank-\u0442\u0430 \u0431\u0430\u0441\u049b\u0430\u0440\u0443",
  "circlesPage.cta.title": "\u0411\u04b1\u043b \u0431\u0435\u0442 \u2014 \u0448\u043e\u043b\u0443.",
  "circlesPage.cta.body": "\u0425\u0430\u0431\u0430\u0440 \u0436\u0456\u0431\u0435\u0440\u0443, \u0442\u04e9\u043b\u0435\u043c\u0434\u0435\u0440 \u0436\u04d9\u043d\u0435 \u043c\u04af\u0448\u0435 \u049b\u043e\u0441\u0443 \u2014 \u04d9\u043c\u0438\u044f\u043d \u0456\u0448\u0456\u043d\u0434\u0435. \u0411\u04b1\u043b \u0431\u0435\u0442 \u0431\u0430\u0440\u043b\u044b\u049b \u0442\u043e\u043f\u0442\u0430\u0440\u0434\u044b \u0431\u0456\u0440 \u043a\u04e9\u0437\u049b\u0430\u0440\u0430\u0441\u043f\u0435\u043d \u0441\u043a\u0430\u043d\u0435\u0440\u043b\u0435\u0443 \u04af\u0448\u0456\u043d.",
  "circlesPage.cta.contacts": "\u041c\u0435\u043a\u0435\u043d\u0436\u0430\u0439 \u043a\u0456\u0442\u0430\u0431\u044b",

  // Glossary /bank/glossary
  "glossaryPage.kicker": "\u0413\u043b\u043e\u0441\u0441\u0430\u0440\u0438\u0439",
  "glossaryPage.headline": "\u04d8\u0440 \u0442\u0435\u0440\u043c\u0438\u043d \u2014 \u0431\u0456\u0440 \u0430\u0431\u0437\u0430\u0446\u0442\u0430.",
  "glossaryPage.lede": "\u0416\u0435\u0442\u0456 \u0442\u043e\u043f \u0431\u043e\u0439\u044b\u043d\u0448\u0430 {count} \u0442\u0435\u0440\u043c\u0438\u043d \u2014 \u0432\u0430\u043b\u044e\u0442\u0430, \u0441\u0435\u043d\u0456\u043c, \u0436\u0438\u043d\u0430\u049b, \u043a\u0440\u0435\u0434\u0438\u0442, \u049b\u04b1\u043f\u0438\u044f\u043b\u044b\u049b, \u04d9\u043b\u0435\u0443\u043c\u0435\u0442\u0442\u0456\u043a, \u044d\u043a\u043e\u0436\u04af\u0439\u0435. \u0406\u0437\u0434\u0435\u0443 \u043d\u0435\u043c\u0435\u0441\u0435 \u0442\u043e\u043f\u0442\u0430\u0440 \u0431\u043e\u0439\u044b\u043d\u0448\u0430 \u0430\u0439\u043d\u0430\u043b\u0434\u044b\u0440\u0443.",
  "glossaryPage.searchPlaceholder": "\u0422\u0435\u0440\u043c\u0438\u043d \u043c\u0435\u043d \u0430\u043d\u044b\u049b\u0442\u0430\u043c\u0430\u043b\u0430\u0440\u0434\u0430\u043d \u0456\u0437\u0434\u0435\u0443\u2026",
  "glossaryPage.searchAria": "\u0413\u043b\u043e\u0441\u0441\u0430\u0440\u0438\u0439\u0434\u0435\u043d \u0456\u0437\u0434\u0435\u0443",
  "glossaryPage.searchEmpty": "\u00ab{q}\u00bb \u0431\u043e\u0439\u044b\u043d\u0448\u0430 \u0435\u0448\u0442\u0435\u04a3\u0435 \u0436\u043e\u049b.",
  "glossaryPage.tocAria": "\u0413\u043b\u043e\u0441\u0441\u0430\u0440\u0438\u0439 \u0442\u043e\u043f\u0442\u0430\u0440\u044b",
  "glossaryPage.readMore": "\u0422\u043e\u043b\u044b\u0493\u044b\u0440\u0430\u049b",
